  root.querySelectorAll('[data-likert-group]').forEach(group =&gt; {
    const dots = group.querySelectorAll('.likert-dot');
    let idx = 0, dir = 1;
    const render = () =&gt; dots.forEach((d, i) =&gt; d.classList.toggle('active', i === idx));
    render();
    track(setInterval(() =&gt; {
      idx += dir;
      if (idx === dots.length - 1 || idx === 0) dir *= -1;
      render();
    }, 480));
  });

  // Dashed connector lines: each ring card -&gt; center of ITEMS stamp.
  // Scoped to the ITEMS box only; only meaningful once the &gt;=960px ring
  // layout is active; recomputed on resize (debounced) and via
  // ResizeObserver so it stays correct across the 760px/960px breakpoints.
  const svg = $('#irw-hero-connectors');
  const inner = $('#irw-hero-items-inner');
  const stampItems = $('#irw-hero-stamp-items');
  const cardIds = ['#irw-hero-card-choice', '#irw-hero-card-likert', '#irw-hero-card-slider'];

  const drawConnectors = () =&gt; {
    if (window.innerWidth &lt; 960) { svg.innerHTML = ''; return; }
    const innerRect = inner.getBoundingClientRect();
    if (innerRect.width === 0) return;
    const items = stampItems.getBoundingClientRect();
    const itemsCenter = {
      x: items.left + items.width / 2 - innerRect.left,
      y: items.top + items.height / 2 - innerRect.top
    };
    let html = '';
    cardIds.forEach(id =&gt; {
      const r = $(id).getBoundingClientRect();
      const cx = r.left + r.width / 2 - innerRect.left;
      const cy = r.bottom - innerRect.top;
      html += `&lt;line x1="${cx}" y1="${cy}" x2="${itemsCenter.x}" y2="${itemsCenter.y}"
                stroke="#1c1c22" stroke-width="2" stroke-dasharray="6 6" stroke-opacity="0.35" /&gt;`;
    });
    svg.innerHTML = html;
  };

  requestAnimationFrame(() =&gt; requestAnimationFrame(drawConnectors));
  let resizeTimer;
  const onResize = () =&gt; { clearTimeout(resizeTimer); resizeTimer = setTimeout(drawConnectors, 120); };
  window.addEventListener('resize', onResize);
  const resizeObserver = new ResizeObserver(() =&gt; drawConnectors());
  resizeObserver.observe(inner);

  invalidation.then(() =&gt; {
    intervals.forEach(id =&gt; clearInterval(id));
    clearTimeout(resizeTimer);
    window.removeEventListener('resize', onResize);
    resizeObserver.disconnect();
  });

  return root;
}

Motivation
Likert-type items (Likert 1932) ask respondents to place themselves on an ordered scale — “strongly disagree” to “strongly agree,” typically with 4 to 7 response categories. The scale is meant to be a transparent window onto the underlying construct: someone who agrees more strongly with an item should pick a higher category. In practice, people also differ systematically in how they use the response scale itself, independent of the construct being measured. Three response styles are especially well documented:

Extreme response style (ERS) — a tendency to favor the endpoints of the scale (the lowest and highest categories) regardless of item content.
Midpoint response style (MRS) — a tendency to favor the middle category, when one exists (only scales with an odd number of categories have a true midpoint).
Acquiescence (net agreement bias) — a tendency toward the “agree” end of the scale across items regardless of content, distinct from ERS/MRS but related in that it’s also a property of how someone uses the scale rather than what they think.

These aren’t just a nuisance for individual items — they’re a known confound: if response style correlates with the substantive score a scale is trying to measure (rather than being pure, construct-irrelevant noise), then style and construct are statistically entangled, and any downstream model (a factor loading, a group comparison, a validity correlation) that treats the raw score as a clean measure of the construct is contaminated by however people use the scale.
This vignette asks three concrete questions of the Likert-format tables in the IRW:

How common is extreme responding, and does it vary a lot across datasets?
Is response style entangled with the substantive score, or does it behave like independent noise?
Does controlling for style — even with a crude method — change a basic substantive conclusion (a factor loading)?


See extreme responding in action
Drag the slider to change how much a simulated respondent’s answers are driven by response style rather than by item content. At \(p = 0\), every answer reflects a fixed, moderate underlying attitude (with a little item-level noise); as \(p\) rises, a growing share of answers instead land on a scale endpoint by chance, regardless of what the item actually asks. The resulting ERS — the proportion of this one simulated respondent’s own answers sitting at an endpoint — is exactly the person-level statistic this vignette computes for every respondent in every IRW Likert-format table below.


